import{_ as o,o as u,c as q,ag as p}from"./chunks/framework.CukOUUOK.js";const c=JSON.parse('{"title":"模糊的边界与权力的游戏：从\\"国家荣誉\\"概念看中国法治的结构性困境","description":"一、引言：一个标签引发的追问 2021年前后，豆瓣平台因对部分主旋律影视作品存在恶意标注标签等行为，被网信部门多次处罚，累计罚款金额巨大，相关功能被要求关闭整改。这一事件表面上是一个平台内容管理问题，…","frontmatter":{"title":"模糊的边界与权力的游戏：从\\"国家荣誉\\"概念看中国法治的结构性困境","categories":"宪法与法治","tags":["法治与宪法","权力"],"description":"一、引言：一个标签引发的追问 2021年前后，豆瓣平台因对部分主旋律影视作品存在恶意标注标签等行为，被网信部门多次处罚，累计罚款金额巨大，相关功能被要求关闭整改。这一事件表面上是一个平台内容管理问题，…","date":"2026-08-27T12:00:00.000Z"},"headers":[],"relativePath":"posts/2026-08-27-blurred-boundaries-national-honor.md","filePath":"posts/2026-08-27-blurred-boundaries-national-honor.md","lastUpdated":1789992750000}'),e={name:"posts/2026-08-27-blurred-boundaries-national-honor.md"};function a(r,t,n,l,s,i){return u(),q("div",null,[...t[0]||(t[0]=[p('<h1 id="模糊的边界与权力的游戏-从-国家荣誉-概念看中国法治的结构性困境" tabindex="-1">模糊的边界与权力的游戏：从&quot;国家荣誉&quot;概念看中国法治的结构性困境 <a class="header-anchor" href="#模糊的边界与权力的游戏-从-国家荣誉-概念看中国法治的结构性困境" aria-label="Permalink to &quot;模糊的边界与权力的游戏：从&quot;国家荣誉&quot;概念看中国法治的结构性困境&quot;">​</a></h1><p>一、引言：一个标签引发的追问</p><p>2021年前后，豆瓣平台因对部分主旋律影视作品存在恶意标注标签等行为，被网信部门多次处罚，累计罚款金额巨大，相关功能被要求关闭整改。这一事件表面上是一个平台内容管理问题，但它牵涉的法律逻辑远比表面所见更为复杂：平台为何被处罚？用户究竟违反了哪一条具体法律？&quot;国家荣誉&quot;这一概念的法律边界在哪里？当法律概念本身缺乏明确定义时，执法的正当性基础又是什么？</p><p>本文试图沿着这一追问链条，从&quot;国家荣誉&quot;的法律定义出发，经由比较法的视角，最终抵达对制度根基的反思。</p><p>二、&quot;违法&quot;的循环：当法律用自身定义自身</p><p>豆瓣被处罚的核心法律依据是《网络安全法》第四十七条和第六十八条。前者规定网络运营者应当加强对其用户发布的信息的管理，发现法律、行政法规禁止发布或者传输的信息的，应当立即停止传输并采取消除等处置措施；后者规定违反上述规定、拒不改正或情节严重的，可处十万元以上五十万元以下罚款，甚至更高额度的处罚。</p><p>问题在于：什么是&quot;法律、行政法规禁止发布或传输的信息&quot;？这一定义指向了《网络信息内容生态治理规定》第六条和第七条。而该规定的第六条第十一项和第七条第九项分别以&quot;法律、行政法规禁止的其他内容&quot;和&quot;其他对网络生态造成不良影响的内容&quot;作为兜底条款。</p><p>这里出现了一个逻辑上的循环：不得发布违法信息→什么是违法信息→违反本规定的就是违法信息→为什么违反本规定就是违法→因为本规定说它是违法的。兜底条款中的&quot;其他&quot;没有指向任何外部可查证的法律条文，而是将解释权完全留给了执法者。</p><p>更关键的是，第六条列举的具体禁止项目中，&quot;损害国家荣誉和利益的&quot;&quot;散布谣言，扰乱社会秩序的&quot;&quot;反对宪法所确定的基本原则的&quot;等表述，其边界高度不确定。什么算&quot;损害国家荣誉&quot;？给一部讲述革命烈士的电影打上&quot;惊悚片&quot;标签算不算？在网上批评某项政策算不算&quot;扰乱社会秩序&quot;？这些问题在法律文本中找不到答案。</p><p>三、&quot;国家荣誉&quot;：一个没有定义的法律概念</p><p>&quot;国家荣誉&quot;这一概念出现在中国法律体系的多个层级。宪法第五十四条规定公民有&quot;维护祖国的安全、荣誉和利益&quot;的义务；《网络信息内容生态治理规定》禁止&quot;损害国家荣誉和利益&quot;的内容；《爱国主义教育法》也有类似表述。</p><p>但没有任何一部法律对&quot;国家荣誉&quot;给出过明确的、可操作的定义。</p><p>宪法释义对&quot;祖国的荣誉&quot;给出的解释是：&quot;中华人民共和国国家的荣誉和尊严&quot;，主要包括国家的尊严不受侵犯、国家的信誉不受破坏、国家的荣誉不受玷污、国家的名誉不受侮辱。这一定义用&quot;荣誉&quot;解释&quot;荣誉&quot;，用&quot;尊严&quot;解释&quot;荣誉&quot;，用&quot;名誉&quot;解释&quot;荣誉&quot;——本质上是同义反复，没有提供任何可操作的判断标准。</p><p>从法理上看，根据《民法典》的规定，荣誉权的主体是自然人、法人和非法人组织。&quot;国家&quot;本身并非民事主体，不享有民法意义上的荣誉权。国家不会&quot;受伤&quot;，不会&quot;丢脸&quot;，不会因为被批评而产生精神痛苦。宪法第五十四条中&quot;维护祖国荣誉&quot;的表述，本质上是一个政治宣示性条款，表达的是一种国家认同的政治期待，而非一个可以精确适用的法律规则。</p><p>然而，当这个模糊的政治概念被层层转译为平台审查的具体操作时——&quot;这个内容可能损害国家荣誉→删除→关闭评论→全面封锁&quot;——它就产生了真实的、具体的限制效果。法律中有&quot;国家荣誉&quot;这个词，但没有任何法律告诉你它具体指什么、边界在哪里、怎么算&quot;损害&quot;。最终解释权落到了执法者手里。</p><p>四、比较视角：宪法爱国主义与&quot;国家荣誉&quot;的逻辑分野</p><p>美国法律体系中不存在&quot;损害国家荣誉&quot;这种罪名或处罚依据。美国最高法院在1989年的&quot;得克萨斯诉约翰逊案&quot;中裁定，焚烧国旗属于受宪法第一修正案保护的言论自由行为。哪怕以最激烈的方式&quot;侮辱&quot;国旗——这个国家最核心的象征——政府也不能因此处罚公民。</p><p>这一差异的根源在于两种截然不同的国家认同逻辑。</p><p>美国政治理论家John Schaar指出，美国公民&quot;不是被血缘或宗教、传统或领土联结在一起的，而是被一个政治理念……被一份契约、对一系列原则的奉献联结在一起的&quot;。美国人每天诵读的效忠誓词（Pledge of Allegiance）的措辞精确地体现了这一点：&quot;I pledge allegiance to the Flag, and to the Republic for which it stands&quot;——&quot;我宣誓效忠国旗，以及它所代表的那个共和国&quot;。效忠的对象不是国家实体本身，而是国旗所代表的那套由宪法所定义的政治秩序和理念。</p><p>林肯在1852年悼念亨利·克莱时说过一句经典的话：&quot;他爱他的国家，部分因为它是他的国家，但主要因为它是自由的国家。&quot;这句话精确地表达了宪法爱国主义的核心逻辑——爱的不是&quot;国家&quot;这个抽象实体，而是这个国家所承载的那套理念和制度。</p><p>&quot;国家荣誉&quot;概念暗含的逻辑是：国家本身是一个有尊严、有名誉的主体，公民有义务维护它的&quot;面子&quot;，谁让国家&quot;丢脸&quot;了谁就犯了错。宪法爱国主义的逻辑完全不同：国家本身不值得无条件忠诚，值得忠诚的是这个国家所承载的那套理念和制度。如果你批评政府、批评政策、甚至焚烧国旗，你不但没有&quot;损害国家&quot;，反而可能恰恰是在践行这个国家最核心的价值——言论自由。</p><p>这就是为什么美国人可以一边烧国旗一边自称爱国——在他们的逻辑里，捍卫&quot;烧国旗的自由&quot;本身就是爱国行为。</p><p>五、法律模糊性的双重面孔</p><p>必须承认，法律概念不可能穷尽一切具体情形，这是立法技术的客观限制。社会现实比任何法条都复杂，如果每个概念都写得极其精确，法律就会变得僵化，无法适应新情况。&quot;公共利益&quot;&quot;社会秩序&quot;这类概念在各国的法律中都存在，美国宪法中的&quot;正当程序&quot;&quot;平等保护&quot;同样需要解释。法律概念的模糊性本身不是问题。</p><p>关键区别在于：模糊之后怎么办？</p><p>在法治成熟的国家，法律模糊之后，由独立的法院通过具体案件来解释和界定边界，形成判例，逐步积累出相对清晰的规则。模糊是起点，司法审查是纠偏机制。在对抗式诉讼中，控辩双方就概念的具体含义进行辩论，法官在判决书中详细说理，上级法院可以推翻下级法院的解释——这一过程本身就是对法律概念的精细化。</p><p>在我们讨论的这套体系中，法律模糊之后，解释权集中在行政管理部门手里，没有独立的外部机构来纠偏。模糊是起点，行政裁量是终点。同样的模糊性，配上不同的纠偏机制，结果完全不同。</p><p>&quot;公序良俗&quot;这一概念在不同法律体系中的运作为此提供了注脚。&quot;公序良俗&quot;在法学界被公认为一个外延高度不确定的概念，在司法实践中容易导致&quot;同案不同判&quot;的现象。在拥有独立司法审查的体系中，法院通过判例逐步积累出相对清晰的适用标准；而在缺乏独立审查机制的体系中，这一概念的适用则高度依赖执法者的主观判断。</p><p>六、违宪审查的缺位：为什么问题长期存在</p><p>中国存在一套备案审查制度——全国人大常委会有权对行政法规、地方性法规、司法解释等进行审查，公民也可以提出审查建议。2023年修改的《立法法》进一步明确了这一机制。但这套机制与真正意义上的违宪审查存在本质区别：</p><p>第一，它不是由独立法院进行的，而是由立法机关自我审查。审查者与被审查者的法律渊源来自同一权力体系，缺乏结构性的独立。</p><p>第二，它不公开审理，没有对抗式辩论，没有判决书说理。公民可以提出审查建议，但审查过程不透明，结果不公开说理。</p><p>第三，公民可以提建议，但没有强制回应机制。建议提出后，审查机关审不审、什么时候审、审完如何回应，主动权完全在审查机关手中。</p><p>第四，它几乎不直接宣布某部法律违宪或无效。</p><p>因此，在最高立法层面，确实缺乏有效的外部约束机制。全国人大是最高国家权力机关，它制定的法律没有外部机构可以进行合宪性审查并宣布其无效。全国人大可以自我修改，但没有任何外部力量可以强制它修改。</p><p>这就解释了为什么&quot;国家荣誉&quot;等模糊概念能够长期存在于法律体系中而不被纠正：不是没人看出来，而是看出来的主体没有制度化的渠道和权力来纠正它。备案审查制度存在，但它的运作方式和实际效果，与法治成熟国家的违宪审查不可同日而语。</p><p>七、从概念模糊到权力运作：一条完整的因果链</p><p>将所有环节串联起来，一条完整的因果链清晰可见：</p><p>法律概念模糊（&quot;国家荣誉&quot;&quot;社会秩序&quot;&quot;不良信息&quot;等缺乏可操作定义）→ 没有独立审查机制来纠正模糊 → 执法者获得过大的自由裁量空间 → 平台为规避风险采取过度自保（全面关闭评论、删除内容）→ 普通用户的正常表达空间被压缩。</p><p>在这一链条中，每一步单独看都&quot;有法可依&quot;，但串起来看，法律的模糊性在每一个环节都被转化为执行者的自由裁量权，最终落在普通用户头上的就是一个&quot;全面禁止&quot;的结果。</p><p>行政处罚需要出具法律文书、引用具体条款，这些形式不是毫无意义的——它们增加了权力行使的成本。不同层级、不同地区的执行也存在差异，说明权力并非铁板一块。社会舆论和公众讨论也对执法行为构成一定约束。但这些约束是松散的、非制度化的、不可预期的，无法替代一个刚性的、制度化的审查机制。</p><p>八、结构性根源：苏联式制度遗产的深层逻辑</p><p>上述反复出现的结构性问题——法律模糊、缺乏审查、权力不受约束——并非偶然的技术缺陷，而是制度设计的结构性特征。</p><p>从历史渊源看，中国共产党的组织原则、国家机构的架构设计、党与国家的关系模式，在建国初期大量借鉴了苏联经验。1954年宪法的起草过程中，苏联方面提供了重要参考。列宁主义政党理论中的&quot;民主集中制&quot;&quot;党领导一切&quot;&quot;先锋队理论&quot;等核心概念，深刻影响了中国制度设计的底层逻辑。</p><p>从权力结构看，核心特征高度相似：权力高度集中，立法、行政、司法不独立，最终都服从于党的统一领导；缺乏独立的外部监督，没有独立法院进行违宪审查，没有独立媒体进行舆论监督，没有反对党进行竞争性制衡；法律的首要功能是&quot;维护社会秩序&quot;和&quot;巩固政权&quot;，而非限制公权力、保护公民权利；概念的模糊性服务于权力弹性——&quot;国家荣誉&quot;&quot;社会秩序&quot;&quot;公共利益&quot;这些模糊概念，本质上是给执行者预留操作空间的制度设计。</p><p>经过七十多年的演变，中国制度与原版苏联模式已有显著差异。经济体制从全面计划经济转向混合经济，社会自主空间大幅扩展，治理技术大量引入了市场机制和绩效考核，合法性来源从纯粹的意识形态转向更多依赖经济绩效。但权力架构的核心逻辑——权力集中且缺乏独立的外部制衡——没有根本改变。</p><p>这就是&quot;制度设计的结构性问题&quot;这一表述的确切含义：这些问题不是某一个领导人的个人问题，不是某一个部门的执行偏差，而是这套权力架构本身的内生特征。只要权力结构不变，这些问题就会反复出现——换一个领导人、换一个部门，同样的问题会以不同的形式再次浮现。</p><p>九、余论：治理效能与权利保障的两个维度</p><p>需要指出的是，指出制度的结构性缺陷，不等于否定其全部治理效能。这套制度在特定历史条件下完成了国家建构、工业化、大规模脱贫等任务，其治理能力不容简单否定。但治理效能和权利保障是两个不同的维度——一个制度可以很&quot;有效&quot;，同时也很&quot;不自由&quot;。这两者不矛盾，甚至经常是同一枚硬币的两面：高度集中的权力在动员资源、推行政策方面具有效率优势，但这种效率恰恰以牺牲权利保障和权力制衡为代价。</p><p>苏联的解体表明，一个缺乏自我纠错能力的制度，即使在特定时期展现出强大的治理能力，其长期稳定性仍然面临严峻挑战。但制度的转型从来不是一个简单的&quot;推倒重来&quot;的过程，它涉及极其复杂的利益格局调整、社会共识凝聚和路径选择。</p><p>回到本文的起点：一个豆瓣用户给电影打了一个标签，这个标签被认定为&quot;损害国家荣誉&quot;，平台被罚款，评论被关闭。从&quot;国家荣誉是什么&quot;这个看似简单的问题出发，我们一路追问到法律概念的循环定义、违宪审查的制度缺位、权力架构的结构性特征。这条追问链条指向的结论是：问题不在于&quot;没有法律&quot;，而在于法律本身的设计就预留了过大的解释空间，同时又缺乏对解释权的制衡。最终的效果是——法律的形式在，法治的实质打了折扣；名义上是&quot;依法治理&quot;，实际上是&quot;依权力意志治理&quot;。</p><p>这不是某一个人的问题，也不是某一个部门的问题。这是一个制度如何回答&quot;谁来约束约束者&quot;这一根本问题的故事。而这个故事，至今没有写完。</p><hr><blockquote><p>本文同步自知乎，<a href="https://zhuanlan.zhihu.com/p/2076236011907060867" target="_blank" rel="noreferrer">查看原文</a>（4 赞）</p></blockquote>',54)])])}const _=o(e,[["render",a]]);export{c as __pageData,_ as default};
